// Route map: the landscape route SVG is drawn in map units and scaled to the screen (measured).
const MAP_SCALE = {'900x405': 1783.13 / 1800, '640x320': 1450 / 2000};
const onMap = (units, where, unitsH = units) => Object.entries(MAP_SCALE).map(([vp, s]) => ({w: +(units * s).toFixed(2), h: +(unitsH * s).toFixed(2), vp, where, basis: 'derived'}));
const css = (w, h, where, vp = 'any') => ({w, h, vp, where, basis: 'css'});
const fix = html => String(html).replaceAll('"./assets/', '"../assets/');

// Copied verbatim where the source keeps the markup in a private constant (no export).
const GRIP = '<svg viewBox="0 0 16 16" shape-rendering="crispEdges"><path fill="currentColor" d="M4 3h3v3H4zm5 0h3v3H9zM4 8h3v3H4zm5 0h3v3H9zM4 13h3v2H4zm5 0h3v2H9z"/></svg>';
const ARROW = '<svg class="front-arrow" viewBox="0 0 20 20" fill="currentColor" shape-rendering="crispEdges" aria-hidden="true"><path d="M3 8h8V4h2v2h2v2h2v2h2v1h-2v2h-2v2h-2v2h-2v-5H3z"/></svg>';
function homePiece(selector, fallback = '') {
  try {
    const host = document.createElement('template'); // inert: no image requests
    host.innerHTML = homeMenuMarkup({profile: {}, run: null});
    const el = host.content.querySelector(selector);
    return el ? el.outerHTML : fallback;
  } catch { return fallback; }
}

const SKILL_NAMES = ['Lift','Double Lift','Luminance','Momentum','Spark Vessel','Last Glimmer','Long Flash','Vitality','Glide Regeneration','Trajectory Guide','Spark Sense','Storage','Prismatic Yield','Kept Light','Dream','Hand Seal','Deep Cache','Proximity','Lasting Pulse','Regenerative Pulse','Light Aegis','Far Search','Rich Cargo','Fleet Return','Close Orbit','Wide Search','Quick Return','Search Spark','Field Impulse','Last Orbit','Clean Break','Thrifty Shell','Returning Shell','Lasting Shell','Frugal Ward','Quick Ward','Deep Ward','Ward Spark','Long Balance','Quick Balance','Deep Dive','Ready Release','Longer Level','Still Point','Falling Release','Balance Spark','Long Spark','Rapid Spark','Storm Runner','Sheltered Pace','Longer Surge','Quick Sparks','Wind Lance','Surge Spark'];
const sampleEvery = (list, n) => list.length <= n ? list : Array.from({length: n}, (_, i) => list[Math.floor(i * list.length / n)]);

const m = id => MEASURED[id] || [];
const FAMILIES = [];
// classLevel: every icon in the family shares the same displayed sizes (one CSS class), so only
// the first rows carry full captions; later rows show the same sizes with the scale label only.
const family = (id, title, note, icons, {classLevel = false} = {}) => FAMILIES.push({id, title, note, icons, classLevel});

// 1. Resource symbols
const RES = ['energy','packed','lift','up','down','uses','clock','auto','music','lock'];
const resNotes = {
  energy: 'The Spark. Also nested inside Stored Sparks at 12 px on its 32 grid (0.6x) and inside skill charms.',
  packed: 'Stored Sparks. Same art as condensedIconMarkup (afterglow-ui.mjs), which the Flight HUD uses as .condensed-icon.',
  up: 'Shown on the Flight HUD Lift button.',
  music: 'Pause menu MUSIC toggle.',
};
family('resource', 'Resource symbols', 'resourceSymbol(kind) in game-symbols.mjs. glow is an alias of energy.', RES.map(kind => ({
  id: 'res-' + kind, name: kind === 'energy' ? 'energy (Spark)' : kind === 'packed' ? 'packed (Stored Sparks)' : kind,
  src: `game-symbols.mjs · resourceSymbol('${kind}')`, html: resourceSymbol(kind), note: resNotes[kind] || '',
  displays: m('res-' + kind),
})));

