  ...CARVINGS.map(name => ({id: 'menu-' + name, name: `${name} (carving)`, src: `menu-icons.mjs · menuIcon('${name}')`, html: menuIcon(name), displays: [...m('menu-' + name), ...(menuExtra[name] || [])]})),
