// ---------- analysis ----------
const parse = html => { const t = document.createElement('template'); t.innerHTML = fix(html).trim(); return t.content.querySelector('svg') || t.content.firstElementChild; };
function geometry(svg, unit) {
  const vb = (svg.getAttribute('viewBox') || '').trim().split(/[\s,]+/).map(Number);
  const [x, y, w, h] = vb.length === 4 ? vb : [0, 0, +svg.getAttribute('width') || 24, +svg.getAttribute('height') || 24];
  return {x, y, w, h, nw: +(w / unit).toFixed(2), nh: +(h / unit).toFixed(2), par: svg.getAttribute('preserveAspectRatio') || 'xMidYMid meet'};
}
function declaredColours(svg) {
  const set = new Set();
  let current = false;
  for (const el of [svg, ...svg.querySelectorAll('*')]) for (const attr of ['fill', 'stroke']) {
    const v = (el.getAttribute(attr) || '').trim().toLowerCase();
    if (!v || v === 'none' || v === 'transparent') continue;
    if (v === 'currentcolor') { current = true; continue; }
    set.add(v);
  }
  return {count: set.size + (current ? 1 : 0), current, list: [...set]};
}
const loadImage = src => new Promise(resolve => { const img = new Image(); img.onload = () => resolve(img); img.onerror = () => resolve(null); img.src = src; });
const dataUrls = new Map();
async function asDataUrl(href) {
  const url = new URL(href, location.href).href;
  if (!dataUrls.has(url)) dataUrls.set(url, fetch(url).then(r => r.blob()).then(blob => new Promise(resolve => { const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.readAsDataURL(blob); })));
  return dataUrls.get(url);
}
const luminance = (r, g, b) => { const f = c => { c /= 255; return c <= .04045 ? c / 12.92 : ((c + .055) / 1.055) ** 2.4; }; return .2126 * f(r) + .7152 * f(g) + .0722 * f(b); };
// Sample one pixel at the centre of every native art cell (4x supersampled raster).
function cellGrid(draw, nw, nh) {
  const k = 4, W = Math.max(1, Math.round(nw)), H = Math.max(1, Math.round(nh));
  const canvas = document.createElement('canvas'); canvas.width = W * k; canvas.height = H * k;
  const c = canvas.getContext('2d'); c.imageSmoothingEnabled = false; draw(c, W * k, H * k);
  const data = c.getImageData(0, 0, W * k, H * k).data, cells = [];
  for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) { const i = ((y * k + 2) * W * k + (x * k + 2)) * 4; cells.push([data[i], data[i + 1], data[i + 2], data[i + 3]]); }
  return {W, H, cells};
}
function outline({W, H, cells}) {
  const solid = (x, y) => x >= 0 && y >= 0 && x < W && y < H && cells[y * W + x][3] >= 128;
  let edge = 0, dark = 0, opaque = 0;
  for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
    if (!solid(x, y)) continue; opaque++;
    if (solid(x - 1, y) && solid(x + 1, y) && solid(x, y - 1) && solid(x, y + 1)) continue;
    edge++; const [r, g, b] = cells[y * W + x]; if (luminance(r, g, b) < .2) dark++;
  }
  if (!opaque || edge === 0) return {label: 'n/a', share: null};
  if (opaque >= W * H * .97) return {label: 'n/a (full-bleed)', share: null};
  const share = dark / edge;
  return {label: share >= .7 ? 'yes' : share >= .35 ? 'partial' : 'no', share};
}
const rasterColours = grid => new Set(grid.cells.filter(p => p[3] >= 128).map(p => p.slice(0, 3).join(','))).size;
// An SVG whose only drawing is one <image> (pickups, card art) is raster art: analyse the source cells.
const imageOnly = svg => { const images = svg.querySelectorAll('image'); return images.length >= 1 && !svg.querySelector('path,rect,circle,polygon,ellipse,line,polyline') && images[0].closest('svg') === svg; };
async function rasterFacts(svg, geo) {
  if (imageOnly(svg)) {
    const image = svg.querySelector('image');
    const img = await loadImage(new URL(image.getAttribute('href'), location.href).href);
    if (!img) return {outline: {label: '?', share: null}, raster: null};
    const iw = +image.getAttribute('width'), ih = +image.getAttribute('height'), ix = +image.getAttribute('x') || 0, iy = +image.getAttribute('y') || 0;
    const sx = img.naturalWidth / iw, sy = img.naturalHeight / ih;
    const crop = [(geo.x - ix) * sx, (geo.y - iy) * sy, geo.w * sx, geo.h * sy];
    const grid = cellGrid((c, w, h) => c.drawImage(img, ...crop, 0, 0, w, h), crop[2], crop[3]);
    return {outline: outline(grid), raster: {colours: rasterColours(grid), w: Math.round(crop[2]), h: Math.round(crop[3]), file: image.getAttribute('href').split('?')[0].replace('../', '')}};
  }
  const copy = svg.cloneNode(true);
  copy.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
  copy.setAttribute('width', geo.nw * 4); copy.setAttribute('height', geo.nh * 4);
  copy.setAttribute('color', '#d6ddc8'); copy.removeAttribute('class'); copy.removeAttribute('style');
  const embedded = [...copy.querySelectorAll('image')], stills = embedded.filter(i => !i.classList.contains('spark-motion')).length;
  for (const image of embedded) { image.setAttribute('href', await asDataUrl(image.getAttribute('href'))); image.removeAttribute('display'); if (image.classList.contains('spark-motion')) image.remove(); }
  const img = await loadImage('data:image/svg+xml;charset=utf-8,' + encodeURIComponent(copy.outerHTML));
  if (!img) return {outline: {label: '?', share: null}, raster: null, embedded: stills};
  return {outline: outline(cellGrid((c, w, h) => c.drawImage(img, 0, 0, w, h), geo.nw, geo.nh)), raster: null, embedded: stills};
}
function scaleOf(d, geo) {
  const sx = d.w / geo.nw, sy = d.h / geo.nh;
  if (geo.par.startsWith('none')) return {s: sx, sx, sy, text: Math.abs(sx - sy) < .01 ? `${sx.toFixed(2)}x` : `${sx.toFixed(2)}×${sy.toFixed(2)}x`};
  const s = geo.par.includes('slice') ? Math.max(sx, sy) : Math.min(sx, sy);
  return {s, sx, sy, text: `${s.toFixed(2)}x`};
}
const isWhole = s => Math.abs(s - Math.round(s)) < .01 && Math.round(s) >= 1;
const fmt = n => Number.isInteger(n) ? String(n) : (+n.toFixed(2)).toString();
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;'}[c]));
// One figure per distinct displayed size; places and viewports are merged into its caption.
function mergeDisplays(list) {
  const map = new Map();
  for (const d of list) {
    const key = `${d.w}x${d.h}`, e = map.get(key) || {w: d.w, h: d.h, vp: new Set(), where: [], basis: new Set()};
    for (const v of String(d.vp).split(' & ')) e.vp.add(v);
    for (const w of String(d.where).split('; ')) if (!e.where.includes(w)) e.where.push(w);
    e.basis.add(d.basis || 'measured'); map.set(key, e);
  }
  return [...map.values()].map(e => ({w: e.w, h: e.h, vp: [...e.vp].sort().reverse().join(' & '), where: e.where.join('; '), basis: [...e.basis].join('+')})).sort((a, b) => b.w * b.h - a.w * a.h);
}
const shortWhere = where => { const parts = where.split('; '); return parts.slice(0, 2).join('; ') + (parts.length > 2 ? ` +${parts.length - 2} more` : ''); };

function figure(svgHtml, w, h, caption, cls = '') {
  const svg = parse(svgHtml);
  svg.removeAttribute('width'); svg.removeAttribute('height');
  svg.style.setProperty('width', w + 'px', 'important'); svg.style.setProperty('height', h + 'px', 'important');
  svg.style.setProperty('image-rendering', 'pixelated');
  const holder = svg.parentElement && svg.parentElement.tagName.toLowerCase() === 'span' ? svg.parentElement : null;
  const fig = document.createElement('figure');
  const tile = document.createElement('div'); tile.className = 'tile';
  if (holder) { holder.style.setProperty('width', w + 'px', 'important'); holder.style.setProperty('height', h + 'px', 'important'); tile.append(holder); } else tile.append(svg);
  fig.append(tile);
  const cap = document.createElement('figcaption'); if (cls) cap.className = cls; cap.innerHTML = caption; fig.append(cap);
  return {fig, svg};
}

const rows = [];
async function renderIcon(icon, famEl, {compact = false} = {}) {
  const unit = icon.unit || 1, root = parse(icon.html);
  if (!root) return;
  const svg = root.tagName.toLowerCase() === 'svg' ? root : root.querySelector('svg');
  const geo = geometry(svg, unit), colours = declaredColours(svg), facts = await rasterFacts(svg, geo);
  const displays = mergeDisplays(icon.displays);
  const row = document.createElement('article'); row.className = 'row'; row.dataset.icon = icon.id;
  famEl.append(row); // attach first so computed styles (shape-rendering from CSS) resolve
  const strip = document.createElement('div'); strip.className = 'strip';
  row.append(strip);
  let nativeSvg = null;
  for (const k of [1, 2, 3]) {
    const {fig, svg: el} = figure(icon.html, +(geo.nw * k).toFixed(2), +(geo.nh * k).toFixed(2), `<b>native ${k}x</b><i>${fmt(geo.nw * k)}×${fmt(geo.nh * k)}px</i>`, 'whole');
    strip.append(fig); if (k === 1) nativeSvg = el;
  }
  const sep = document.createElement('span'); sep.className = 'sep'; strip.append(sep);
  if (!displays.length) { const none = document.createElement('span'); none.className = 'none'; none.textContent = 'No displayed size measured or declared in CSS for this icon (it may still have call sites the samples do not reach).'; strip.append(none); }
  const shown = [];
  for (const d of displays) {
    const sc = scaleOf(d, geo), whole = geo.par.startsWith('none') ? isWhole(sc.sx) && isWhole(sc.sy) : isWhole(sc.s);
    shown.push({...d, scale: +sc.s.toFixed(3), scaleText: sc.text, whole});
    const size = `${fmt(d.w)}${d.h !== d.w ? '×' + fmt(d.h) : ''}px`;
    const caption = compact ? `<b>${size} = ${sc.text}</b>` : `<b>${size} = ${sc.text}</b><span class="basis">${esc(d.basis)} · ${esc(d.vp)}</span><i>${esc(shortWhere(d.where))}</i>`;
    strip.append(figure(icon.html, d.w, d.h, caption, whole ? 'whole' : 'frac').fig);
  }
  const fractional = shown.filter(d => !d.whole);
  const computed = getComputedStyle(nativeSvg).shapeRendering;
  const crispAttr = svg.getAttribute('shape-rendering') === 'crispEdges';
  const nestedCrisp = !crispAttr && !!svg.querySelector('[shape-rendering="crispEdges"]');
  const info = {
    family: famEl.dataset.family, id: icon.id, name: icon.name, src: icon.src,
    grid: `${fmt(geo.nw)}×${fmt(geo.nh)}`, viewBox: svg.getAttribute('viewBox'), unit,
    colours: facts.raster ? facts.raster.colours : colours.count,
    colourBasis: facts.raster ? `raster ${facts.raster.file} ${facts.raster.w}×${facts.raster.h}` : colours.current ? 'markup, incl. currentColor' : 'markup',
    embedsRaster: !!facts.embedded, palette: colours.list, outline: facts.outline.label,
    outlineShare: facts.outline.share == null ? null : +facts.outline.share.toFixed(2),
    crisp: computed === 'crispedges' ? (crispAttr ? 'yes (attr)' : 'yes (CSS)') : nestedCrisp ? 'nested only' : 'no',
    displays: shown, fractional: fractional.length, note: icon.note || '',
  };
  rows.push(info);
  const chip = (text, cls = '') => `<span class="chip ${cls}">${esc(text)}</span>`;
  const head = document.createElement('div');
  head.innerHTML = `<div class="row-head"><strong>${esc(icon.name)}</strong><span class="src">${esc(icon.src)}</span></div>
   <div class="facts">${chip(`grid ${info.grid}`)}${chip(`viewBox ${info.viewBox}${unit !== 1 ? ` · ${fmt(unit)} units per art px` : ''}`, 'no')}${chip(`${info.colours} colours${facts.raster ? ' (raster)' : colours.current ? ' (currentColor)' : ''}`)}${info.embedsRaster ? chip('embeds a PNG sprite', 'warn') : ''}${chip(`outline: ${info.outline}${info.outlineShare != null ? ` (${Math.round(info.outlineShare * 100)}%)` : ''}`, info.outline === 'yes' ? '' : 'no')}${chip(`crispEdges: ${info.crisp}`, info.crisp.startsWith('yes') ? '' : 'warn')}${chip(`${fractional.length}/${shown.length} displayed sizes fractional`, fractional.length ? 'warn' : '')}</div>
   ${icon.note ? `<p class="fam-note">${esc(icon.note)}</p>` : ''}${compact ? '<p class="fam-note">Same class-level sizes as the first rows of this family (captions there).</p>' : ''}`;
  row.prepend(...head.children);
}

async function main() {
  const host = document.querySelector('#inventory');
  const nav = document.createElement('nav'); nav.className = 'legend'; nav.setAttribute('aria-label', 'Families');
  nav.innerHTML = '<b>Families</b> ' + FAMILIES.map(f => `<a href="#family-${f.id}" style="color:#cfe0c6;margin-right:10px">${esc(f.title)}</a>`).join('');
  host.before(nav);
  for (const fam of FAMILIES) {
    const section = document.createElement('section'); section.dataset.family = fam.id; section.id = 'family-' + fam.id;
    section.innerHTML = `<h2>${esc(fam.title)} <small class="src">(${fam.icons.length} shown)</small></h2><p class="fam-note">${esc(fam.note)}</p>`;
    host.append(section);
    for (const [index, icon] of fam.icons.entries()) {
      try { await renderIcon(icon, section, {compact: fam.classLevel && index >= 2}); }
      catch (error) { console.error('Icon failed', icon.id, error); }
    }
  }
  const grids = new Set(rows.map(r => r.grid)), frac = rows.reduce((n, r) => n + r.fractional, 0), cases = rows.reduce((n, r) => n + r.displays.length, 0);
  document.querySelector('#totals').innerHTML = `<span><b>${rows.length}</b> icons</span><span><b>${FAMILIES.length}</b> families</span><span><b>${grids.size}</b> native grids</span><span><b>${frac}</b> of ${cases} icon × displayed-size cases fractional</span><span><b>${rows.filter(r => r.fractional).length}</b> icons shown at a fractional scale somewhere</span>`;
  window.__inventory = {families: FAMILIES.map(f => ({id: f.id, title: f.title, shown: f.icons.length, classLevel: f.classLevel})), rows, totals: {icons: rows.length, families: FAMILIES.length, grids: [...grids], fractional: frac, cases, relics: artifactPortraitIds.length, skills: SKILL_NAMES.length, cards: CARD_ART_IDS.length, bonuses: bonusIds.length}};
  document.documentElement.dataset.inventoryReady = 'true';
}
main();
